	('e6ed4fdf-c0c5-492e-8e8e-d6d27f0db6f9', 'cron_setup', 'ChatGPT duplicate detection cron jobs configured', '{"jobs": ["chatgpt-ai-analysis", "chatgpt-ai-analysis-priority", "chatgpt-analysis-cleanup", "chatgpt-analysis-monitoring"], "schedules": {"cleanup": "0 2 * * * (daily at 2 AM)", "monitoring": "0 * * * * (every hour)", "regular_analysis": "*/10 * * * * (every 10 minutes)", "priority_analysis": "*/3 9-17 * * 1-5 (every 3 minutes during business hours)"}, "description": "Automated ChatGPT Vision API duplicate detection system"}', '2026-04-22 21:42:23.69057+00'),
	('68407a63-efbe-47df-9edc-f1c1217be278', 'cron_update', 'Fixed broken cron jobs and replaced with working ai-insights-worker', '{"added_jobs": ["ai-insights-worker-scheduled", "ai-insights-worker-priority"], "removed_jobs": ["chatgpt-ai-analysis", "chatgpt-ai-analysis-priority"], "new_schedules": {"ai_insights_regular": "*/10 * * * * (every 10 minutes)", "ai_insights_priority": "*/5 9-17 * * 1-5 (every 5 minutes during business hours)"}, "migration_date": "2026-04-22T21:42:23.945759+00:00", "target_function": "ai-insights-worker"}', '2026-04-22 21:42:23.945759+00'),
	('60c2ad72-2c07-4ec0-9c07-6f562cc56f95', 'cron_cleanup', 'Removed broken weekly email cron job with placeholders', '{"reason": "Contains unresolved placeholders [SET_SUPABASE_URL] and [SET_SERVICE_ROLE_KEY]", "alternative": "Backend EmailReportsService handles email automation with proper cron jobs", "removed_job": "weekly-email-reports", "backend_crons": ["Daily at 19:00", "Weekly Monday at 09:00", "Dynamic processing every 15 minutes"], "migration_date": "2026-04-22T21:42:24.160041+00:00"}', '2026-04-22 21:42:24.160041+00'),
	('c66281d4-ddbb-4610-b39f-c662ede52f1e', 'setup_instructions', 'Service role key configuration ready', '{"instructions": "After rotating service role key, run: SELECT public.configure_service_role_key(''NEW_SERVICE_ROLE_KEY'');", "security_note": "Never commit service role keys to version control", "migration_file": "20250126_configure_service_key_setting.sql"}', '2026-04-22 21:42:24.341868+00'),
	('c35c31d2-2c21-4543-aa46-de9a7ce12e88', 'cron_cleanup', 'Removed duplicate pg_cron email jobs', '{"reason": "Conflict with NestJS EmailReportsService", "removed_jobs": ["daily-email-reports-direct", "weekly-email-reports-direct"], "migration_date": "2026-04-22T21:42:25.984614+00:00"}', '2026-04-22 21:42:25.984614+00'),
	('7de3bafd-986e-42f1-8801-edd4d72583fa', 'cron_update', 'Updated AI analysis cron jobs to work all day using cron functions', '{"method": "cron_functions", "reason": "User requested all-day AI analysis coverage", "changes": {"daily_job": "0 8,20 * * * (8AM and 8PM daily)", "priority_job": "*/10 * * * * (every 10 minutes, all day)", "off_hours_job": "0 */2 * * * (every 2 hours, all day)", "business_hours_job": "*/5 9-17 * * 1-5 (every 5 minutes, business hours)"}, "timestamp": "2026-04-22T21:42:29.167742+00:00", "executed_by": "migration_v3"}', '2026-04-22 21:42:29.167742+00'),
	('7d35a686-4ca8-48fd-96c4-e2d8b28bbb8f', 'cron_cleanup', 'Cleaned up redundant AI cron jobs', '{"reason": "Replaced HTTP POST jobs with reliable SQL function jobs", "kept_jobs": ["ai-screenshot-processor", "ai-insights-generator-hourly", "ai-insights-generator-daily", "ai-cleanup-failed", "daily-email-report-v2", "weekly-email-report-v2", "cleanup-url-slices"], "migration": "20260101_cleanup_redundant_cron_jobs", "removed_jobs": ["ai-insights-worker-every-15min", "ai-insights-worker-daily", "ai_session_2min", "unnamed run_ai_insights_priority jobs"]}', '2026-04-22 21:42:29.886044+00'),
