INSERT INTO "public"."warning_templates" ("id", "name", "title", "message", "severity", "category", "description", "is_system", "created_at", "updated_at") VALUES
	('209590d6-783b-4bd6-aba6-e10b8308c939', 'low_productivity_warning', 'Productivity Reminder', 'Your recent activity levels have been below average. Please ensure you are staying focused and productive during work hours. If you need assistance or have concerns, please reach out to your supervisor.', 'medium', 'productivity', 'Warning for employees with consistently low productivity scores', true, '2026-04-22 21:42:20.823455+00', '2026-04-22 21:42:20.823455+00'),
	('49e07908-6a14-41ca-8b51-00a9c8a55690', 'attendance_reminder', 'Attendance Reminder', 'Please remember to maintain regular work hours and notify your supervisor of any planned absences. Consistent attendance is important for team productivity and project success.', 'medium', 'attendance', 'Reminder about attendance policies and expectations', true, '2026-04-22 21:42:20.823455+00', '2026-04-22 21:42:20.823455+00'),
	('4f7aa444-051a-4166-9261-39a684e819f4', 'time_tracking_compliance', 'Time Tracking Compliance', 'Please ensure you are properly tracking your work time and taking appropriate breaks. Accurate time tracking helps us maintain transparency and ensure fair compensation.', 'low', 'policy', 'Reminder about proper time tracking procedures', true, '2026-04-22 21:42:20.823455+00', '2026-04-22 21:42:20.823455+00'),
	('75a8bdbc-cbcd-4c90-9dc7-a5ea274a0971', 'security_reminder', 'Security Reminder', 'Please remember to follow company security policies: lock your screen when away, use strong passwords, and report any suspicious activity immediately.', 'high', 'policy', 'Important security policy reminder', true, '2026-04-22 21:42:20.823455+00', '2026-04-22 21:42:20.823455+00'),
	('eed91216-64e0-45d8-b3a5-35bc320d46b8', 'performance_improvement', 'Performance Improvement Notice', 'Your recent performance metrics indicate areas for improvement. Please schedule a meeting with your supervisor to discuss development opportunities and support available to help you succeed.', 'high', 'productivity', 'Formal notice for performance improvement requirements', true, '2026-04-22 21:42:20.823455+00', '2026-04-22 21:42:20.823455+00'),
